 public function bootPlatform(PlatformContext $ctx): void { parent::bootPlatform($ctx); foreach(['api.routes','admin.pages','permissions.check'] as $cap)$ctx->capabilities()->require($cap); $db=$ctx->database();$http=$ctx->http();$perms=$ctx->permissions();$settings=$this->settingsFrom($db,'support',$this->settings());$mailSettings=$this->settingsFrom($db,'mail',[]);$site=$this->siteUrl($ctx);$svc=$this->service($ctx,$settings,$mailSettings,$site);$poll=$http->softRateLimitMiddleware(180,60,['throttled'=>true,'messages'=>[],'ticket'=>null,'agents_online'=>null]);$write=$http->rateLimitMiddleware(40,60);$protected=[$http->authMiddleware(),$http->permissionMiddleware()];$q=static fn(PlatformRequestInterface $r,string $key,mixed $default=null):mixed=>$r->query()[$key]??$default;
