 $http->get('/support/active',function(PlatformRequestInterface $r)use($svc,$db,$q){$pack=$svc->activeForVisitor((string)$q($r,'visitor_key',$_COOKIE['jasefly_support_vk']??'')); if(!$pack){PlatformResponse::json(['data'=>null]);return;} PlatformResponse::json(['data'=>['ticket'=>$pack['ticket'],'messages'=>$pack['messages'],'agents_online'=>(new SupportPresence($db))->hasOnlineAgents()]]);},[$poll]);
 $http->post('/support/tickets',function(PlatformRequestInterface $r)use($svc){$res=$svc->createTicket((string)$r->input('visitor_key'),(string)$r->input('body',$r->input('message','')),$this->str($r->input('page_url')),$this->str($r->header('User-Agent',$this->str($r->input('user_agent')))));$this->result($res,201,['ticket'=>$res['ticket']??null,'messages'=>$res['messages']??[]]);},[$write]);
 $http->get('/support/tickets/{publicId}',function(PlatformRequestInterface $r,string $id)use($svc,$q){$ticket=$svc->getByPublicId($id,(string)$q($r,'visitor_key',$r->input('visitor_key','')));if(!$ticket){PlatformResponse::error('Not found',404);return;}PlatformResponse::json(['data'=>$ticket]);},[$poll]);
 $http->get('/support/tickets/{publicId}/messages',function(PlatformRequestInterface $r,string $id)use($svc,$db,$q){$key=(string)$q($r,'visitor_key');$ticket=$svc->getByPublicId($id,$key);if(!$ticket){PlatformResponse::error('Not found',404);return;}$svc->visitorHeartbeat($id,$key);PlatformResponse::json(['data'=>['ticket'=>$svc->getByPublicId($id,$key),'messages'=>$svc->listMessages((int)$ticket['id'],(int)$q($r,'after_id',0)),'agents_online'=>(new SupportPresence($db))->hasOnlineAgents()]]);},[$poll]);
 $http->post('/support/tickets/{publicId}/messages',function(PlatformRequestInterface $r,string $id)use($svc){$res=$svc->postVisitorMessage($id,(string)$r->input('visitor_key'),(string)$r->input('body',$r->input('message','')));$this->result($res,201,['message'=>$res['message']??null,'bot_message'=>$res['bot_message']??null,'ticket'=>$res['ticket']??null]);},[$write]);
 $http->post('/support/tickets/{publicId}/contact',function(PlatformRequestInterface $r,string $id)use($svc){$res=$svc->setContact($id,(string)$r->input('visitor_key'),$this->str($r->input('email')),$this->str($r->input('social',$r->input('contact_social'))),$this->str($r->input('social_type',$r->input('contact_social_type'))));$this->result($res,200,$res['ticket']??null);},[$write]);
 $http->post('/support/heartbeat',function(PlatformRequestInterface $r)use($svc,$settings){$id=(string)$r->input('public_id');$key=(string)$r->input('visitor_key');$ticket=(bool)$r->input('leaving',false)&&!empty($settings['require_contact_on_leave'])?$svc->markAwaitingContact($id,$key):$svc->visitorHeartbeat($id,$key);if(!$ticket){PlatformResponse::error('Not found',404);return;}PlatformResponse::json(['data'=>$ticket]);},[$poll]);
 $agent=function(PlatformRequestInterface $r)use($perms){$u=$r->user()??[];if(!$perms->can($u,'support.agent')&&!$perms->can($u,'support.manage'))PlatformResponse::error('Forbidden: support.agent required',403);};$manage=function(PlatformRequestInterface $r)use($perms){$perms->require($r->user()??[],'support.manage');};
