 private function service(PlatformContext $ctx,array $settings,array $mail,string $site): SupportService {$db=$ctx->database();$inbox=$this->inboxUrl($db,$site);$storage=(string)$ctx->config()->get('storage',sys_get_temp_dir());$notifier=new SupportNotifier($settings,$mail,rtrim($storage,'/\\').'/logs',$ctx->mail(),$ctx->http(),$inbox);return new SupportService($db,$settings,new SupportPresence($db),new SupportBot($db,(string)($settings['bot_fallback']??'')),new SupportEmailGuard(),$notifier);}
 private function settingsFrom($db,string $name,array $fallback): array {try{$r=$db->one('SELECT settings FROM modules WHERE name=?',[$name]);$v=json_decode((string)($r['settings']??''),true);return is_array($v)?array_replace($fallback,$v):$fallback;}catch(\Throwable){return $fallback;}}
 private function siteUrl(PlatformContext $ctx): string {$db=$ctx->database();$c=[(string)$ctx->config()->get('url',''),(string)$ctx->config()->get('public_url','')];try{$r=$db->one('SELECT canonical_base_url FROM seo_settings LIMIT 1');array_unshift($c,(string)($r['canonical_base_url']??''));}catch(\Throwable){}foreach($c as $v){$v=rtrim(trim($v),'/');if(preg_match('#^https?://#i',$v))return $v;}return '';}
 private function inboxUrl($db,string $site): string {try{$r=$db->one('SELECT admin_base_path FROM site_settings LIMIT 1');$p=trim((string)($r['admin_base_path']??''),'/');}catch(\Throwable){$p='';}return $site.'/'.($p?:'admin').'/support';}private function str(mixed $v):?string{return is_string($v)?$v:null;}private function result(array $r,int $status,mixed $data):void{if(!($r['ok']??false)){PlatformResponse::json(['success'=>false,'error'=>$r['error']??'Îøèáêà','code'=>$r['code']??null],($r['code']??'')==='contact_required'?409:422);return;}PlatformResponse::json(['data'=>$data],$status);}
